root.querySelectorAll('.feature-row').forEach(row=>{const buttons=[...row.querySelectorAll('[data-feature-before]')];const preview=row.querySelector('[data-feature-before-preview]');const previewImage=row.querySelector('[data-feature-preview-image]');const afterMedia=row.querySelector('[data-feature-after-media]');const video=afterMedia?.querySelector('video');const conditionalCopy=row.closest('.maizebus-case-page')&&row.querySelector('.feature-copy h2')?.textContent.trim()==='Horizontal progress bar'?row.querySelector('.feature-copy p:last-of-type'):null;const defaultConditionalCopy=conditionalCopy?.textContent;const showBefore=index=>{const selected=buttons.find(button=>Number(button.dataset.featureBefore)===index);const image=selected?.querySelector('img');buttons.forEach(button=>{const active=button===selected;button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label',active?'Click again to return to the after view':button.dataset.beforeLabel)});previewImage.hidden=!image;if(image){previewImage.src=image.src;previewImage.alt=selected.dataset.beforeLabel||''}else{previewImage.removeAttribute('src');previewImage.alt=''}if(conditionalCopy)conditionalCopy.textContent=index===2?'Usability tests flagged the horizontal progress bar as unconventional, so I iterated toward familiar Google/Apple Maps patterns to build trust through recognizable conventions rather than requiring users to learn a new mental model (on top of everything else new about campus).':defaultConditionalCopy;preview.hidden=false;afterMedia.hidden=true;if(video)video.pause()};const showAfter=()=>{buttons.forEach(button=>{button.setAttribute('aria-pressed','false');button.setAttribute('aria-label',button.dataset.beforeLabel)});preview.hidden=true;previewImage.hidden=true;afterMedia.hidden=false;if(video)video.play().catch(()=>{})};buttons.forEach(button=>button.addEventListener('click',()=>showBefore(Number(button.dataset.featureBefore))));if(row.closest('.maizebus-case-page')&&row.querySelector('.feature-copy h2')?.textContent.trim()==='Horizontal progress bar')showBefore(3)});root.querySelectorAll('.solution-video').forEach(scoreVideo=>{const scoreWrap=scoreVideo.closest('.solution-video-wrap');let touchControlsTimer;const showControls=()=>{scoreVideo.controls=true};const hideControls=()=>{scoreVideo.controls=false};scoreWrap.addEventListener('pointerenter',event=>{if(event.pointerType!=='touch')showControls()});scoreWrap.addEventListener('pointerleave',event=>{if(event.pointerType!=='touch'&&!scoreVideo.matches(':focus'))hideControls()});scoreVideo.addEventListener('focus',showControls);scoreVideo.addEventListener('blur',()=>{if(!scoreWrap.matches(':hover'))hideControls()});scoreWrap.addEventListener('pointerdown',event=>{if(event.pointerType==='touch'){showControls();clearTimeout(touchControlsTimer);touchControlsTimer=setTimeout(()=>{if(!scoreVideo.matches(':focus'))hideControls()},4000)}})})

const lightbox=document.createElement('div');
lightbox.className='image-lightbox';
lightbox.hidden=true;
lightbox.setAttribute('role','dialog');
lightbox.setAttribute('aria-modal','true');
lightbox.setAttribute('aria-hidden','true');
lightbox.setAttribute('aria-label','Image preview');
lightbox.innerHTML='<button class="image-lightbox-close" type="button" aria-label="Close image">×</button><figure><img alt=""><figcaption></figcaption></figure>';
document.body.append(lightbox);
const lightboxImage=lightbox.querySelector('img');
const lightboxCaption=lightbox.querySelector('figcaption');
const lightboxClose=lightbox.querySelector('.image-lightbox-close');
let lightboxOpener=null;
let lightboxCloseTimer;
const closeLightbox=()=>{
 if(lightbox.hidden||!lightbox.classList.contains('is-open'))return;
 lightbox.classList.remove('is-open');
 lightbox.setAttribute('aria-hidden','true');
 document.body.classList.remove('lightbox-open');
 clearTimeout(lightboxCloseTimer);
 lightboxCloseTimer=setTimeout(()=>{
  lightbox.hidden=true;
  if(lightboxOpener?.isConnected)lightboxOpener.focus({preventScroll:true});
 },320);
};
const openLightbox=source=>{
 clearTimeout(lightboxCloseTimer);
 lightboxOpener=source;
 lightboxImage.src=source.currentSrc||source.src;
 lightboxImage.alt=source.alt||'';
 lightboxCaption.textContent=source.hasAttribute('data-lightbox-caption')?source.dataset.lightboxCaption:source.closest('figure')?.querySelector('figcaption')?.textContent||source.alt||'';
 lightbox.hidden=false;
 lightbox.setAttribute('aria-hidden','false');
 document.body.classList.add('lightbox-open');
 requestAnimationFrame(()=>lightbox.classList.add('is-open'));
 lightboxClose.focus({preventScroll:true});
};
root.querySelectorAll('img').forEach(img=>{
 if(img.closest('.feature-before-thumb,.feature-before-preview,.maizebus-cover-poster,.solstove-cover-image'))return;
 img.classList.add('lightbox-trigger');
 img.tabIndex=0;
 img.setAttribute('role','button');
 img.setAttribute('aria-label',img.alt?`Open image: ${img.alt}`:'Open image preview');
 img.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();openLightbox(img)});
 img.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openLightbox(img)}});
});
lightboxClose.addEventListener('click',closeLightbox);
lightbox.addEventListener('click',event=>{if(event.target===lightbox)closeLightbox()});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeLightbox()});
